        // dp[i][j][k][last] = number of sequences of length i, with j humps, k valleys, ending with y-value 'last'
        // But to determine if adding a new point creates a hump or valley, we need the previous point.
        // So we need: dp[i][j][k][prev][curr]
        // i: number of vertices (from 1 to n)
        // j: number of humps (0 to t)
        // k: number of valleys (0 to t-1)
        // prev: previous y-value (1 to 4)
        // curr: current y-value (1 to 4)

        // Base case: i=1, only one vertex, no humps or valleys possible yet.
        // But we need at least 2 vertices to have a segment.
        // Let's start with i=2.

        // Actually, let's use:
        // dp[i][j][k][prev][curr] where i is the number of vertices processed so far.
        // For i=1: we have just one vertex. We can't define prev.
        // Let's handle i=1 separately or start from i=2.

        // Alternative approach:
        // dp[i][j][k][last] where last is the last y-value, and we store the count.
        // When we add a new value 'next', we look at the previous value 'prev' (which is 'last' in the state) and the one before that.
        // This requires knowing the last two values.

        // So let's use: dp[i][j][k][a][b] where a is the (i-1)-th y-value and b is the i-th y-value.
        // i ranges from 2 to n.
        // j ranges from 0 to t.
        // k ranges from 0 to t-1.
        // a, b range from 1 to 4.

        long[][][][] dp = new long[n + 1][t + 1][t][5][5];

        // Initialize for i=2
        // For i=2, we have two vertices. No humps or valleys can be formed (need at least 3 vertices).
        // So j=0, k=0.
        for (int a = 1; a <= 4; a++) {
            for (int b = 1; b <= 4; b++) {
                if (a != b) { // no segment parallel to Ox-axis
                    dp[2][0][0][a][b] = 1;
                }
            }
        }

        // Transition
        for (int i = 3; i <= n; i++) {
            for (int j = 0; j <= t; j++) {
                for (int k = 0; k <= t - 1; k++) {
                    for (int a = 1; a <= 4; a++) {
                        for (int b = 1; b <= 4; b++) {
                            if (dp[i - 1][j][k][a][b] == 0) continue;
                            for (int c = 1; c <= 4; c++) {
                                if (b == c) continue; // no segment parallel to Ox-axis

                                // Check if a new hump or valley is formed at position i-1 (which is 'b')
                                // The three consecutive points are a, b, c
                                // Hump: a < b > c
                                // Valley: a > b < c

                                int newJ = j;
                                int newK = k;

                                if (a < b && b > c) {
                                    newJ = j + 1;
                                } else if (a > b && b < c) {
                                    newK = k + 1;
                                }
                                // If neither, then it's a straight line or same direction, no new hump/valley
                                // Note: since a != b and b != c, the only cases are:
                                // a < b < c (increasing, no hump/valley at b)
                                // a > b > c (decreasing, no hump/valley at b)
                                // a < b > c (hump)
                                // a > b < c (valley)

                                if (newJ <= t && newK <= t - 1) {
                                    dp[i][newJ][newK][b][c] += dp[i - 1][j][k][a][b];
                                }
                            }
                        }
                    }
                }
            }
        }

        // Sum up all dp[n][t][t-1][a][b] for all a, b
        long result = 0;
        for (int a = 1; a <= 4; a++) {
            for (int b = 1; b <= 4; b++) {
                result += dp[n][t][t - 1][a][b];
            }
        }

        System.out.println(result);
    }
