        // dp[i][j][k][last] where:
        // i = number of vertices processed (from 1 to n)
        // j = number of humps (peaks) so far
        // k = number of valleys so far
        // last = last y value (1 to 4)
        //
        // We need to count sequences of length n with y values in {1,2,3,4}
        // such that:
        // - no two consecutive y values are equal (no horizontal segments)
        // - number of peaks (j where y[j-1] < y[j] > y[j+1]) is exactly t
        // - number of valleys (j where y[j-1] > y[j] < y[j+1]) is exactly t-1
        //
        // Note: peaks and valleys are counted at internal positions j (2 <= j <= n-1)
        //
        // We can use DP where at each step we track the last two y values to determine
        // if the previous position was a peak or valley.
        //
        // Let's define dp[i][j][k][a][b] where:
        // i = current position (1-indexed, so we've placed i vertices)
        // j = number of peaks so far
        // k = number of valleys so far
        // a = y value at position i-1
        // b = y value at position i
        //
        // When we add a new value c at position i+1, we can check if position i was a peak or valley:
        // - If a < b > c, then position i is a peak, so j increases by 1
        // - If a > b < c, then position i is a valley, so k increases by 1
        //
        // Base case: i=2, we have two values a and b (a != b)
        // j=0, k=0 initially since no internal positions have been checked yet
        //
        // We need to reach i=n with j=t and k=t-1

        // dp[i][j][k][a][b]
        // i ranges from 2 to n
        // j ranges from 0 to t
        // k ranges from 0 to t-1
        // a, b range from 1 to 4

        long[][][][][] dp = new long[n + 1][t + 1][t][5][5];

        // Initialize for i=2
        for (int a = 1; a <= 4; a++) {
            for (int b = 1; b <= 4; b++) {
                if (a != b) {
                    dp[2][0][0][a][b] = 1;
                }
            }
        }

        // Transition
        for (int i = 2; i < n; i++) {
            for (int j = 0; j <= t; j++) {
                for (int k = 0; k <= t - 1; k++) {
                    for (int a = 1; a <= 4; a++) {
                        for (int b = 1; b <= 4; b++) {
                            if (dp[i][j][k][a][b] == 0) continue;
                            for (int c = 1; c <= 4; c++) {
                                if (b == c) continue; // no horizontal segment
                                int newJ = j;
                                int newK = k;
                                // Check if position i is a peak or valley
                                if (a < b && b > c) {
                                    newJ = j + 1;
                                } else if (a > b && b < c) {
                                    newK = k + 1;
                                }
                                if (newJ <= t && newK <= t - 1) {
                                    dp[i + 1][newJ][newK][b][c] += dp[i][j][k][a][b];
                                }
                            }
                        }
                    }
                }
            }
        }

        long result = 0;
        for (int a = 1; a <= 4; a++) {
            for (int b = 1; b <= 4; b++) {
                result += dp[n][t][t - 1][a][b];
            }
        }

        System.out.println(result);
    }
