import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int t = scanner.nextInt();
        scanner.close();

        long result = countCamels(n, t);
        System.out.println(result);
    }

    static long countCamels(int n, int t) {
        // dp[i][lastY][humps][valleys][lastDir]
        // lastDir: 0 = increasing, 1 = decreasing
        // We need exactly t humps and t-1 valleys
        // humps: local maxima (y[j-1] < y[j] > y[j+1])
        // valleys: local minima (y[j-1] > y[j] < y[j+1])

        // Let's use memoization or iterative DP
        // i: position (1 to n)
        // lastY: previous y value (1 to 4)
        // humps: number of humps so far
        // valleys: number of valleys so far
        // lastDir: direction of last segment (0 = up, 1 = down)

        // At position i, we have placed y[i]. The direction from y[i-1] to y[i] is lastDir.
        // When we add y[i+1], we can determine if y[i] is a hump or valley based on lastDir and new direction.

        // Let's define:
        // dp[i][y][h][v][dir] = number of ways to have placed i vertices, with y[i] = y,
        // h humps, v valleys, and the direction from y[i-1] to y[i] is dir (0=up, 1=down)

        // Base case: i=1, we have y[1]. No direction yet.
        // i=2: we have y[1] and y[2]. Direction is determined.

        // Let's use a 5D array or map. Since n <= 20, t <= 10, y in 1..4, humps <= 10, valleys <= 10
        // humps max is t, valleys max is t-1

        // dp[i][y][h][v][dir] where i from 1 to n, y from 1 to 4, h from 0 to t, v from 0 to t-1, dir from 0 to 1

        // For i=1: no direction. We can handle this separately.
        // For i=2: direction is determined by y[1] and y[2].

        // Let's use:
        // dp[i][y][h][v][dir] for i >= 2
        // For i=1, we just track y[1]

        long[][][][][] dp = new long[n + 1][5][t + 1][t][2];

        // Initialize for i=1
        // We'll handle i=1 separately and start from i=2

        // For i=1, we have y[1] = 1, 2, 3, 4
        // No humps, no valleys, no direction yet

        // Let's use a different approach:
        // dp[i][y][h][v][dir] where dir is the direction from y[i-1] to y[i]
        // For i=1, we don't have a direction. So let's start from i=2.

        // For i=2:
        // y[1] can be 1-4, y[2] can be 1-4, y[1] != y[2]
        // dir = 0 if y[2] > y[1], dir = 1 if y[2] < y[1]
        // h = 0, v = 0

        for (int y1 = 1; y1 <= 4; y1++) {
            for (int y2 = 1; y2 <= 4; y2++) {
                if (y1 == y2) continue;
                int dir = (y2 > y1) ? 0 : 1;
                dp[2][y2][0][0][dir] += 1;
            }
        }

        // For i from 3 to n:
        for (int i = 3; i <= n; i++) {
            for (int y = 1; y <= 4; y++) {
                for (int h = 0; h <= t; h++) {
                    for (int v = 0; v <= t - 1; v++) {
                        for (int dir = 0; dir <= 1; dir++) {
                            long count = dp[i - 1][y][h][v][dir];
                            if (count == 0) continue;

                            // Try all possible next y values
                            for (int nextY = 1; nextY <= 4; nextY++) {
                                if (nextY == y) continue; // no parallel to Ox-axis means y[i] != y[i+1]

                                int newDir = (nextY > y) ? 0 : 1;
                                int newH = h;
                                int newV = v;

                                // Check if y[i-1] to y[i] to y[i+1] forms a hump or valley
                                // dir is direction from y[i-1] to y[i]
                                // newDir is direction from y[i] to y[i+1]

                                // Hump: y[i-1] < y[i] > y[i+1]
                                // This means dir = 0 (up) and newDir = 1 (down)
                                if (dir == 0 && newDir == 1) {
                                    newH = h + 1;
                                }
                                // Valley: y[i-1] > y[i] < y[i+1]
                                // This means dir = 1 (down) and newDir = 0 (up)
                                else if (dir == 1 && newDir == 0) {
                                    newV = v + 1;
                                }

                                if (newH <= t && newV <= t - 1) {
                                    dp[i][nextY][newH][newV][newDir] += count;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Sum up all valid states at i = n
        long total = 0;
        for (int y = 1; y <= 4; y++) {
            for (int dir = 0; dir <= 1; dir++) {
                total += dp[n][y][t][t - 1][dir];
            }
        }

        return total;
    }
}
